const cfg = $('Config').first().json;
const BS = String.fromCharCode(92);
const NL = String.fromCharCode(10);
const isTrue = v => v === true || String(v).toLowerCase() === 'true';
const testMode = isTrue(cfg.testMode);
const ccPrincipal = isTrue(cfg.ccPrincipal);
const emailRe = new RegExp('^[^@ ]+@[^@ ]+[.][a-z]{2,24}$');
const badTlds = ['comm', 'con', 'cmo', 'ocm', 'coom', 'cm', 'om', 'inn', 'orgg', 'nett'];
const norm = v => (v === undefined || v === null) ? '' : String(v).trim();
const splitEmails = v => norm(v).split(NL).join(';').split(',').join(';').split(';').map(e => e.trim().toLowerCase()).filter(e => e.length > 0);
const uniq = a => a.filter((x, i) => a.indexOf(x) === i);
const get = (row, name) => {
  if (row[name] !== undefined) return row[name];
  const key = Object.keys(row).find(k => k.trim().toLowerCase() === name.toLowerCase());
  return key ? row[key] : '';
};
const esc = s => norm(s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const qEsc = s => norm(s).split(BS).join(BS + BS).split("'").join(BS + "'");
const generic = ['', 'coordinator', 'school coordinator', 'sir', 'madam', 'sir/madam', 'na', 'n/a', '-', 'principal', 'none', 'nil'];

const out = [];
let idx = 0;
for (const item of $input.all()) {
  const row = item.json;
  const school = norm(get(row, 'School'));
  if (!school) continue;
  idx += 1;
  const state = norm(get(row, 'State'));
  const city = norm(get(row, 'City'));
  const issuesRaw = norm(get(row, 'Email Issues (check manually)'));
  const issueList = splitEmails(issuesRaw);
  const extraIssues = [];
  const valid = list => list.filter(e => {
    if (issueList.indexOf(e) !== -1) return false;
    const tld = e.split('.').pop();
    if (!emailRe.test(e) || badTlds.indexOf(tld) !== -1) { extraIssues.push(e); return false; }
    return true;
  });
  let to;
  let cc = [];
  if (ccPrincipal) {
    to = uniq(valid(splitEmails(get(row, 'Coordinator Email'))));
    cc = uniq(valid(splitEmails(get(row, 'Principal Email')))).filter(e => to.indexOf(e) === -1);
  } else {
    to = uniq(valid(splitEmails(get(row, 'Send To (all valid emails)'))));
  }
  const allIssues = uniq(issueList.concat(extraIssues));

  const names = norm(get(row, 'Coordinator Name')).split(';').map(n => n.trim()).filter(n => generic.indexOf(n.toLowerCase()) === -1);
  const greeting = names.length ? 'Dear ' + names.join(', ') + ',' : 'Dear Sir/Madam,';

  const tpl = norm(cfg.subjectTemplate) || 'Results - {School} ({State})';
  const subject = (testMode ? '[TEST] ' : '') + tpl.split('{School}').join(school).split('{State}').join(state).split('{City}').join(city);

  const students = norm(get(row, 'Students Ranked')) || '0';
  const teachers = norm(get(row, 'Teachers Ranked')) || '0';
  const fileName = norm(get(row, 'File Name'));
  const driveLink = norm(get(row, 'Drive Link'));
  const m = driveLink.match(new RegExp('/d/([^/?#]+)')) || driveLink.match(new RegExp('[?&]id=([^&#]+)'));
  const fileId = m ? m[1] : '';

  const htmlBody = '<p>' + esc(greeting) + '</p>'
    + '<p>Greetings from the ' + esc(cfg.organisationName) + '.</p>'
    + '<p>We are pleased to share the results for <b>' + esc(school) + '</b>' + (city ? ', ' + esc(city) : '') + '.</p>'
    + '<ul><li>Students ranked: <b>' + esc(students) + '</b></li><li>Teachers ranked: <b>' + esc(teachers) + '</b></li></ul>'
    + '<p>We request you to review the results and share them with the concerned students and teachers.</p>'
    + '<p>For any clarification, please reply to this email.</p>'
    + '<p>Warm regards,<br>' + esc(cfg.senderName) + '<br>' + esc(cfg.senderDesignation) + '<br>' + esc(cfg.organisationName) + '</p>';

  out.push({ json: {
    rowKey: 'row-' + idx,
    school, state, city,
    coordinatorName: norm(get(row, 'Coordinator Name')),
    to: to.join(', '),
    cc: cc.join(', '),
    hasRecipient: to.length > 0,
    emailIssues: allIssues.join('; '),
    studentsRanked: students,
    teachersRanked: teachers,
    fileName, driveLink, fileId,
    tenantId: norm(get(row, 'Tenant ID')),
    driveQuery: "name = '" + qEsc(fileName) + "' and '" + qEsc(cfg.schoolFilesFolderId) + "' in parents and trashed = false",
    greeting, subject, htmlBody,
  } });
}
return out;
